#pragma once

/**
 * @file web_assets.hpp
 * @brief Lightweight Single-Page Application (HTML5/CSS3/minimal JS) embedded in Flash .rodata.
 * Zero external CDN dependencies; operates fully in air-gapped ZeroTier networks.
 */

static const char INDEX_HTML[] = R"rawliteral(<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>ZeroTier ESP32-S3</title><style>*{box-sizing:border-box;margin:0;padding:0}body{font-family:sans-serif;background:#0f172a;color:#f8fafc;padding:12px;line-height:1.4}.c{max-width:720px;margin:auto}header{display:flex;justify-content:space-between;align-items:center;margin-bottom:12px;padding-bottom:8px;border-bottom:1px solid #334155}h1{font-size:1.2rem;color:#38bdf8}.b{font-size:.75rem;padding:3px 8px;border-radius:10px;font-weight:600}.b-on{background:#065f46;color:#34d399}.b-off{background:#7f1d1d;color:#f87171}.g{display:grid;grid-template-columns:1fr;gap:10px;margin-bottom:10px}@media(min-width:600px){.g{grid-template-columns:1fr 1fr}}.card{background:#1e293b;border:1px solid #334155;border-radius:8px;padding:12px}.card h2{font-size:.85rem;color:#94a3b8;margin-bottom:8px;text-transform:uppercase}.r{display:flex;justify-content:space-between;padding:4px 0;font-size:.85rem}.v{font-weight:600;font-family:monospace}.p-bg{background:#334155;border-radius:4px;height:12px;overflow:hidden;margin-top:8px}.p-fill{background:#38bdf8;height:100%;width:0%;transition:width .2s}input[type=file]{display:block;width:100%;margin:8px 0;font-size:.8rem;color:#94a3b8}button{background:#0284c7;color:#fff;border:none;border-radius:6px;padding:8px;font-weight:600;cursor:pointer;width:100%}button:disabled{background:#475569;cursor:not-allowed}#ota-msg{margin-top:6px;font-size:.8rem}</style></head><body><div class="c"><header><h1>ZeroTier ESP32-S3</h1><span id="badge-zt" class="b b-off">ZT Offline</span></header><div class="g"><div class="card"><h2>System Telemetry</h2><div class="r"><span>Uptime</span><span id="v-up" class="v">--</span></div><div class="r"><span>Core Temp</span><span id="v-temp" class="v">--</span></div><div class="r"><span>Free Heap</span><span id="v-heap" class="v">--</span></div><div class="r"><span>Free PSRAM</span><span id="v-psram" class="v">--</span></div><div class="r"><span>Ping Latency</span><span id="v-ping" class="v">--</span></div></div><div class="card"><h2>ZeroTier Network</h2><div class="r"><span>Status</span><span id="v-zt-st" class="v">--</span></div><div class="r"><span>Node ID</span><span id="v-node" class="v">--</span></div><div class="r"><span>Network ID</span><span id="v-nwid" class="v">--</span></div><div class="r"><span>Assigned IP</span><span id="v-ip" class="v">--</span></div><div class="r"><span>Active Slot</span><span id="v-slot" class="v">--</span></div></div></div><div class="card"><h2>OTA Firmware Update</h2><p style="font-size:.8rem;color:#94a3b8">Upload ESP32-S3 firmware image (.bin) to inactive partition.</p><input type="file" id="f-ota" accept=".bin"><button id="btn-ota" onclick="uploadFw()">Upload & Flash</button><div class="p-bg" id="p-wrap" style="display:none"><div class="p-fill" id="p-bar"></div></div><div id="ota-msg"></div></div></div><script>const E=i=>document.getElementById(i);function fmtUp(s){var d=Math.floor(s/86400),h=Math.floor(s%86400/3600),m=Math.floor(s%3600/60),c=s%60;return(d?d+'d ':'')+[h,m,c].map(v=>String(v).padStart(2,'0')).join(':')}function fmtB(b){return b>1048576?(b/1048576).toFixed(1)+' MB':(b/1024).toFixed(0)+' KB'}function poll(){fetch('/api/status').then(r=>r.json()).then(d=>{E('v-up').textContent=fmtUp(d.uptime_seconds);E('v-temp').textContent=d.temp_celsius>-50?d.temp_celsius.toFixed(1)+' °C':'N/A';E('v-heap').textContent=fmtB(d.free_heap_internal);E('v-psram').textContent=fmtB(d.free_psram);var pt=d.ping_target||'target';E('v-ping').textContent=d.ping_online?(d.ping_latency_ms+' ms ('+pt+')'):('Offline ('+pt+')');E('v-zt-st').textContent=d.zt_online?'ONLINE':'OFFLINE';var bg=E('badge-zt');bg.className='b '+(d.zt_online?'b-on':'b-off');bg.textContent='ZT '+(d.zt_online?'Online':'Offline');E('v-node').textContent=d.zt_node_id||'--';E('v-nwid').textContent=d.zt_nwid||'--';E('v-ip').textContent=d.zt_ip||'None';E('v-slot').textContent=d.active_slot||'ota_0'}).catch(()=>{})}setInterval(poll,2500);poll();function uploadFw(){var f=E('f-ota').files[0];if(!f){alert('Select .bin file');return}var b=E('btn-ota'),w=E('p-wrap'),p=E('p-bar'),m=E('ota-msg');b.disabled=true;w.style.display='block';m.style.color='#38bdf8';m.textContent='Uploading...';var x=new XMLHttpRequest();x.open('POST','/update',true);x.setRequestHeader('Content-Type','application/octet-stream');x.upload.onprogress=e=>{if(e.lengthComputable){var pct=Math.round((e.loaded/e.total)*100);p.style.width=pct+'%';m.textContent='Uploading: '+pct+'%'}};x.onload=()=>{if(x.status===200){p.style.width='100%';m.style.color='#34d399';m.textContent='Update success! Rebooting in 2s...';setTimeout(()=>location.reload(),6000)}else{m.style.color='#f87171';m.textContent='Update failed: '+x.responseText;b.disabled=false}};x.onerror=()=>{m.style.color='#f87171';m.textContent='Network error during upload';b.disabled=false};x.send(f)}</script></body></html>)rawliteral";
